ALTER SEQUENCE public.invoice_number_seq RESTART WITH 1000;
ALTER SEQUENCE public.receipt_number_seq RESTART WITH 1000;
ALTER SEQUENCE public.maintenance_request_number_seq RESTART WITH 1000;

DROP TABLE IF EXISTS seed_months;
CREATE TEMP TABLE seed_months AS
SELECT g AS m,
       (date_trunc('month', CURRENT_DATE - (g || ' months')::interval))::date AS period_start,
       (date_trunc('month', CURRENT_DATE - (g || ' months')::interval) + INTERVAL '1 month' - INTERVAL '1 day')::date AS period_end
FROM generate_series(0, 4) AS g;










